<?php
declare(strict_types=1);
$directory=$argv[1];$loader=require dirname(__DIR__,2).'/vendor/autoload.php';$loader->addPsr4('App\\',$directory.'/app',true);$app=require $directory.'/bootstrap/app.php';$app->container->get(Elang\Database\Migrator::class)->migrate();$users=$app->container->get(Elang\Auth\Users::class);$owner=$users->create('Owner','owner@example.test','A unique account passphrase','admin',true);$viewer=$users->create('Viewer','viewer@example.test','A second account passphrase','user',true);$outsider=$users->create('Other','other@example.test','A third account passphrase','user',true);$teams=$app->container->get(Elang\Tenancy\Teams::class);$team=$teams->create($owner,'First organization');$other=$teams->create($outsider,'Other organization');$teams->accept($viewer,$teams->invite($owner,$team['id'],$viewer->email,'viewer'));$tokens=$app->container->get(Elang\Auth\ApiTokens::class);$ownerToken=$tokens->issue($owner,'owner',['teams:read','teams:write']);$viewerToken=$tokens->issue($viewer,'viewer',['teams:read','teams:write']);$otherToken=$tokens->issue($outsider,'other',['teams:read','teams:write']);
function check(bool $result,string $message):void { if(!$result) throw new RuntimeException($message); }
$api=function(string $path,string $method='GET',?array $data=null,?string $token=null,array $headers=[])use($app,$ownerToken) { $r=Symfony\Component\HttpFoundation\Request::create('http://localhost'.$path,$method,[],[],[],['CONTENT_TYPE'=>'application/json'],$data===null?null:json_encode($data));$r->headers->add(['Authorization'=>'Bearer '.($token??$ownerToken),'Accept'=>'application/json']+$headers);return $app->handle($r); };
$path='/api/teams/'.$team['id'].'/projects';$created=$api($path,'POST',['title'=>'Private project','team_id'=>$other['id']],null,['Idempotency-Key'=>'project-create-test']);check($created->getStatusCode()===201,'Create: '.$created->getContent());$row=json_decode($created->getContent(),true)['data'];$id=$row['id'];check($row['team_id']===$team['id'],'Forged tenant was accepted');check($api($path,'GET',null,$otherToken)->getStatusCode()===404,'Cross-tenant list');check($api($path,'POST',['title'=>'Denied'],$viewerToken)->getStatusCode()===403,'Viewer write');check($api($path.'/'.$id,'PUT',['title'=>'Updated','status'=>'active','version'=>1])->getStatusCode()===200,'Update');check($api($path.'/'.$id,'PUT',['title'=>'Stale','status'=>'done','version'=>1])->getStatusCode()===409,'Stale version');check($api('/api/teams/'.$other['id'].'/projects/'.$id,'DELETE',['version'=>2])->getStatusCode()===404,'Cross-tenant delete');
$session=new Symfony\Component\HttpFoundation\Session\Session(new Symfony\Component\HttpFoundation\Session\Storage\MockArraySessionStorage());$browser=function(string $path,string $method='GET',array $data=[])use($app,$session) { $r=Symfony\Component\HttpFoundation\Request::create('http://localhost'.$path,$method,$data);$r->setSession($session);return $app->handle($r); };$r=Symfony\Component\HttpFoundation\Request::create('/');$r->setSession($session);$app->container->get(Elang\Auth\Auth::class)->login($r,$owner);$page=$browser('/workspace/team/'.$team['id']);check($page->getStatusCode()===200,'Workspace: '.$page->getContent());check(str_contains($page->getContent(),'Private')||str_contains($page->getContent(),'Updated'),'Project render');check($browser('/operations')->getStatusCode()===200,'Operations');check($browser('/workspace/team/'.$team['id'].'/projects','POST',['title'=>'Missing CSRF'])->getStatusCode()===419,'CSRF');$invite=$browser('/workspace/team/'.$team['id'].'/invites','POST',['_token'=>$session->get('_csrf'),'email'=>'invite@example.test','role'=>'viewer']);check($invite->getStatusCode()===200,'Invitation');check(str_contains($invite->headers->get('Cache-Control'),'no-store'),'Invitation caching');check($invite->headers->get('Referrer-Policy')==='no-referrer','Invitation referrer');
check($api($path.'/'.$id,'DELETE',['version'=>2])->getStatusCode()===204,'Delete');$teams->remove($owner,$team['id'],$viewer->id);check($api($path,'GET',null,$viewerToken)->getStatusCode()===404,'Revocation');echo "SaaS: workspace, scoped API, roles, isolation, optimistic writes, invitations, CSRF, operations, and revocation passed.\n";
